package com.careerpilot.modules.scheduling.entity;import com.careerpilot.modules.auth.entity.User;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="scheduled_exam_reschedule_history")@Getter@Setter@NoArgsConstructor public class ScheduledExamRescheduleHistory{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="scheduled_exam_id")private ScheduledExam scheduledExam;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="student_user_id")private User student;@Column(name="old_start",nullable=false)private Instant oldStart;@Column(name="old_end",nullable=false)private Instant oldEnd;@Column(name="new_start",nullable=false)private Instant newStart;@Column(name="new_end",nullable=false)private Instant newEnd;@Column(name="changed_at",nullable=false)private Instant changedAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(changedAt==null)changedAt=Instant.now();}}
